<style>
.ops-hero{background:linear-gradient(135deg,#132137,#1e315b);color:#fff;border-radius:16px;padding:20px 22px;margin-bottom:12px}.ops-hero h1{margin:0 0 5px;font-size:22px}.ops-hero p{margin:0;color:#dce5f2;font-size:10px}.ops-card{background:#fff;border:1px solid #e3e8ef;border-radius:13px;padding:15px;margin-top:12px}.ops-filter{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;align-items:end}.ops-filter label{font-size:9px;color:#66758a}.ops-table{width:100%;border-collapse:collapse;margin-top:12px}.ops-table th,.ops-table td{padding:9px 8px;border-bottom:1px solid #edf0f5;text-align:left;font-size:10px;vertical-align:top}.ops-table th{color:#77869a;font-size:8px;text-transform:uppercase}.ops-table small{display:block;color:#7b899c;margin-top:3px}.ops-empty{padding:22px;text-align:center;color:#7b899c}.ops-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.ops-metric{background:#fff;border:1px solid #e3e8ef;border-radius:11px;padding:13px}.ops-metric small{font-size:8px;color:#78869a;text-transform:uppercase}.ops-metric b{display:block;font-size:21px;color:#132137;margin-top:4px}@media(max-width:760px){.ops-summary{grid-template-columns:1fr}.ops-table{display:block;overflow:auto}}
</style>
